import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function FeeStructure() {
  const [fee, setFee] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/fees")
      .then((res) => {
        console.log("Fee API response:", res.data); // ✅ check in console
        if (res.data.success) {
          setFee(res.data.data); // ✅ use res.data.data not res.data
        }
      })
      .catch((err) => {
        console.error("Error loading fee structure:", err);
      })
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Loading...</p>;
  if (!fee) return <p>No fee data found.</p>;

  return (
    <div className="fee-structure">
      <h2>Fee Structure for Academic Year {fee.academicYear}</h2>

      <div
        className="fee-notes"
        dangerouslySetInnerHTML={{ __html: fee.notes }}
      />

      <table className="fee-table">
        <thead>
          <tr>
            <th>Fee Type</th>
            <th>Amount (₹)</th>
            <th>Description</th>
          </tr>
        </thead>
        <tbody>
          {fee.items.map((item) => (
            <tr key={item._id}>
              <td>{item.title}</td>
              <td>{item.amount}</td>
              <td>
                <div
                  dangerouslySetInnerHTML={{ __html: item.description }}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
